from pynwb import NWBHDF5IO
f = 'data/sub-m11/sub-m11_ses-03_behavior+ophys.nwb'
with NWBHDF5IO(f, 'r', load_namespaces=True) as io:
    nwb = io.read()
    if nwb.intervals:
        for k,v in nwb.intervals.items():
            print('INTERVAL', k)
            try:
                print('  columns', list(v.colnames))
                print('  nrows', len(v.id[:]))
                if len(v.id[:]) > 0:
                    row = v[0]
                    print('  first_row_keys', list(row.keys()) if hasattr(row, 'keys') else type(row))
            except Exception as e:
                print('  table_err', e)
    for mod_name, mod in nwb.processing.items():
        for if_name, obj in mod.data_interfaces.items():
            print('INTERFACE', mod_name, if_name, type(obj).__name__)
            for attr in ['time_series','roi_response_series']:
                if hasattr(obj, attr):
                    try:
                        series = getattr(obj, attr)
                        print(' ', attr, list(series.keys()))
                        for sname, sobj in list(series.items())[:5]:
                            try:
                                print('   ', sname, 'shape', getattr(sobj.data, 'shape', None), 'rate', getattr(sobj, 'rate', None), 'unit', getattr(sobj, 'unit', None))
                            except Exception as e:
                                print('   ', sname, 'err', e)
                    except Exception as e:
                        print(' ', attr, 'ERR', e)
